window.kbPageData["views/entry/k-4f89a981c8bc89ff"] = {"key":"entry/k-4f89a981c8bc89ff","state":{"route":"entry/k-4f89a981c8bc89ff"},"node":{"id":"k-4f89a981c8bc89ff","mode":"k","title":"两集合容斥公式","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["两集合并集的容斥公式"],"qs":["国考 2023 副省级 行测#70"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"两个集合的并集人数等于两个集合的人数之和减去交集人数。在给定总人数中，两项均未参加的人数等于总人数减去并集人数。","review":{"definition":"两个集合的并集人数等于两个集合的人数之和减去交集人数。在给定总人数中，两项均未参加的人数等于总人数减去并集人数。","explanation":"分别统计两项培训人数时，两项都参加的人被计入两次，所以求并集时要减去一次交集。也可以直接把三个互不重叠的部分相加。本题只参加防病培训的有100人，只参加育种培训的有45人，两项都参加的有121人，故两项均未参加的有287−(100+45+121)=21人，对应A项。","references":[],"evidence":"总数-只参加防病培训的人数-只参加育种培训的人数","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#70":{"paper":"国考 2023 副省级 行测","n":70,"mod":"数量关系","src":["503793642e845de9795f.pdf",13],"asrc":["ecade1ff5af69283232e.pdf",21],"card":"b609151a69bc0724c0b91316","links":[{"id":"k-4f89a981c8bc89ff","role":"解题依据","why":"两项培训的并集由两类单项参训人员和同时参训人员组成，其补集为两项均未参训的人员。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-4f89a981c8bc89ff":[["国考 2023 副省级 行测#70"]]}};
